"use client";

import { useFramecnTheme } from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";
import {
  DropdownMenuItemRow,
  dropdownMenuItemStyle,
  dropdownMenuItemStyleContext,
} from "@/components/framecn/dropdown-menu-item";
import type {
  DropdownMenuItemState,
  DropdownMenuItemStyle,
  DropdownMenuItemStyleContext,
} from "@/components/framecn/dropdown-menu-item";

export type ContextMenuState = "opened" | "closed";

export interface ContextMenuProps {
  state?: ContextMenuState;
  style?: ContextMenuStyle;
  items?: string[];
  highlightedIndex?: number;
  pressedIndex?: number;
  itemStyles?: (DropdownMenuItemStyle | undefined)[];
  theme?: Partial<FramecnTheme>;
  className?: string;
}

const WIDTH = 200;

export interface ContextMenuStyle {
  opacity: number;
  scale: number;
  translateY: number;
}

export interface ContextMenuStyleContext {
  panelBg: string;
  panelBorder: string;
  radius: number;
  itemCtx: DropdownMenuItemStyleContext;
}

export const contextMenuStyleContext = (
  theme: FramecnTheme
): ContextMenuStyleContext => ({
  itemCtx: dropdownMenuItemStyleContext(theme),
  panelBg: theme.popover,
  panelBorder: theme.border,
  radius: theme.radius,
});

export const contextMenuStyle = (
  state: ContextMenuState,
  _ctx: ContextMenuStyleContext
): ContextMenuStyle => {
  switch (state) {
    case "opened": {
      return { opacity: 1, scale: 1, translateY: 0 };
    }
    default: {
      return { opacity: 0, scale: 0.95, translateY: -8 };
    }
  }
};

const rowState = (
  i: number,
  highlightedIndex: number,
  pressedIndex: number
): DropdownMenuItemState => {
  if (i === pressedIndex) {
    return "press";
  }
  if (i === highlightedIndex) {
    return "hover";
  }
  return "idle";
};

export const ContextMenu = ({
  state = "closed",
  style,
  items = ["Back", "Reload", "Save As…", "Inspect"],
  highlightedIndex = -1,
  pressedIndex = -1,
  itemStyles,
  theme: themeOverride,
  className,
}: ContextMenuProps) => {
  const theme = useFramecnTheme(themeOverride);
  const ctx = contextMenuStyleContext(theme);
  const v = style ?? contextMenuStyle(state, ctx);
  return (
    <div
      className={className}
      style={{
        background: ctx.panelBg,
        border: `1px solid ${ctx.panelBorder}`,
        borderRadius: Math.max(0, ctx.radius - 2),
        boxShadow:
          "0 4px 6px -1px rgb(0 0 0 / 10%), 0 2px 4px -2px rgb(0 0 0 / 10%)",
        boxSizing: "border-box",
        display: "flex",
        flexDirection: "column",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        gap: 0,
        opacity: v.opacity,
        padding: 4,
        transform: `translateY(${v.translateY}px) scale(${v.scale})`,
        transformOrigin: "top left",
        width: WIDTH,
      }}
    >
      {items.map((item, i) => {
        const override = itemStyles?.[i];
        const rowStyle =
          override ??
          dropdownMenuItemStyle(
            rowState(i, highlightedIndex, pressedIndex),
            ctx.itemCtx
          );
        return (
          <DropdownMenuItemRow
            key={item}
            style={rowStyle}
            label={item}
            width="100%"
            theme={themeOverride}
          />
        );
      })}
    </div>
  );
};

"use client";

import { easings, useFramecnTheme, useStateTransition } from "@/lib/framecn-ui";
import type { FramecnTheme, Step } from "@/lib/framecn-ui";
import {
  contextMenuStyle,
  contextMenuStyleContext,
} from "@/components/framecn/context-menu";
import type {
  ContextMenuState,
  ContextMenuStyle,
} from "@/components/framecn/context-menu";

export const DEFAULT_DURATION = 10;

export const tweenContextMenuStyle = (
  a: ContextMenuStyle,
  b: ContextMenuStyle,
  t: number
): ContextMenuStyle => ({
  opacity: a.opacity + (b.opacity - a.opacity) * t,
  scale: a.scale + (b.scale - a.scale) * t,
  translateY: a.translateY + (b.translateY - a.translateY) * t,
});

export interface ContextMenuTransitionOptions {
  theme?: Partial<FramecnTheme>;
  mode?: "light" | "dark";
  speed?: number;
  defaultDuration?: number;
}

export const useContextMenuTransition = (
  steps: Step<ContextMenuState>[],
  opts: ContextMenuTransitionOptions = {}
): ContextMenuStyle => {
  const {
    theme: themeOverride,
    mode,
    speed = 1,
    defaultDuration = DEFAULT_DURATION,
  } = opts;
  const theme = useFramecnTheme(themeOverride, mode);
  const ctx = contextMenuStyleContext(theme);
  const { from, to, progress } = useStateTransition(
    steps,
    "closed",
    speed,
    defaultDuration
  );
  const t = easings.out(progress);
  return tweenContextMenuStyle(
    contextMenuStyle(from, ctx),
    contextMenuStyle(to, ctx),
    t
  );
};
